import {applyTheme,setTheme} from './appearance.js';
import {b64,un64,derive,seal,decrypt} from './vault.js';
import {split,ledger,balances,settlements,parseCSV,importSplitwise,recordAbsence} from './core.js';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>(n/100).toLocaleString('it-IT',{style:'currency',currency:'EUR'}),today=()=>new Date().toLocaleDateString('sv-SE'),uid=()=>crypto.randomUUID(),short=n=>n.replace(' (rimosso)','').split(' ')[0],initial=n=>n.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',wallet:'M3 5h16v4H3z M3 9h18v12H3z M16 14h5',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16 M8 14h2 M14 14h2',clown:'M5 8a9 9 0 0 0 14 0 M4 5l3 3-4 2 M20 5l-3 3 4 2 M8 16q4 6 8 0 M12 10v3',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',sync:'M20 8a8 8 0 0 0-14-3L3 8 M3 3v5h5 M4 16a8 8 0 0 0 14 3l3-3 M21 21v-5h-5',plus:'M12 5v14 M5 12h14',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4',arrow:'M5 12h14 M14 7l5 5-5 5'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.home}"/></svg>`;
let adminOwner=false,adminUnlocked=false,adminData={url:'',hasToken:false},subscriberDevices=[],pushEnabled=false;let changes=0;let stale=false;let state=null,key=null,envelope=null,view='home',current=null,me=localStorage.getItem('cc-me')||'m1',limit=30,query='',settings={url:''},revision=Number(localStorage.getItem('cc-revision')||0),dirty=localStorage.getItem('cc-dirty')==='1',saving=Promise.resolve(),syncing=false,installPrompt=null,rankMode='presence';
async function encrypt(data,k=key,salt=envelope.salt){return seal(data,k,salt);}
function validState(s){if(!s||!Array.isArray(s.groups)||!s.groups.length||s.groups.some(g=>!Array.isArray(g.members)||!Array.isArray(g.expenses)||!Array.isArray(g.events)||!Array.isArray(g.posts)))throw Error('Archivio non valido');return s;}
function group(){return state.groups.find(g=>g.id===current)||state.groups[0];}function member(id,g=group()){return g.members.find(m=>m.id===id)?.name||'Ex membro';}function active(){return group().members.filter(m=>!m.archived);}function avatar(m,i=0){return `<span class="avatar" style="background:${['#e7dff6','#dcece6','#f0dfd7','#dce5f4','#eadfed','#f0e9d9'][i%6]}">${esc(initial(m.name))}</span>`;}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function persist(){if(stale)throw Error('Un’altra scheda ha aggiornato l’archivio. Ricarica prima di modificare.');changes++;dirty=true;localStorage.setItem('cc-dirty','1');const snapshot=JSON.parse(JSON.stringify(state));saving=saving.catch(()=>{}).then(async()=>{envelope=await encrypt(snapshot);localStorage.setItem('cc-vault',JSON.stringify(envelope));}).catch(e=>{toast('Salvataggio non riuscito: '+e.message);throw e;});return saving;}
async function commit(message){try{await persist();render();if(message)toast(message);if(settings.url)sync().catch(e=>toast(e.message));}catch(e){toast(e.message);}}
function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
async function backup(){await saving;download('clown-club-'+today()+'.clown',JSON.stringify(envelope));toast('Backup cifrato scaricato. Conserva anche la password.');}
function showModal(title,html,submit){const d=$('#modal');d.innerHTML=`<div class="modalhead"><h2>${esc(title)}</h2><button type="button" aria-label="Chiudi" id="closemodal">×</button></div>${html}`;$('#closemodal').onclick=()=>d.close();if(submit){const f=d.querySelector('form');f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('[type=submit]');b.disabled=true;try{await submit(new FormData(f),f);d.close();}catch(err){let target=d.querySelector('.error');if(!target){target=document.createElement('p');target.className='error';f.append(target);}target.textContent=err.message;}finally{b.disabled=false;}};}d.showModal();}
function lockScreen(error=''){const existing=!!localStorage.getItem('cc-vault');$('#app').innerHTML=`<main class="lockscreen"><button class="icon login-theme" id="login-theme" data-action="theme" aria-label="Cambia tema">☾</button><section class="card lockcard"><div class="brand"><span class="brandmark">♧</span> clown club<span class="badge">PRIVATE</span></div><div class="lockart">🎪</div><h1>Il conto torna.<br>Voi meno.</h1><p>Spese condivise, amici discutibili.<br>Entra nel vostro piccolo circo.</p><form id="unlock"><label for="password">Password del circo</label><input id="password" type="password" autocomplete="current-password" required placeholder="La sai. O chiedi al capo clown."><label class="inlinecheck"><input id="remember" type="checkbox" checked> Ricordami su questo dispositivo</label><button class="primary" type="submit">Entra nel club ${icon('arrow')}</button><p class="error" id="unlockerror">${esc(error)}</p></form><div class="footerhint">${existing?'Il tuo archivio è cifrato su questo dispositivo.':'Primo accesso: usa la password del circo.'}</div></section></main>`;$('#login-theme').onclick=()=>{setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');};applyTheme();$('#unlock').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;if(!crypto.subtle){$('#unlockerror').textContent='Apri l’app tramite il suo indirizzo HTTPS per usare l’archivio cifrato.';b.disabled=false;return;}try{const password=$('#password').value,login=await clubLogin(password);if(login==='wrong'){$('#unlockerror').textContent='Password del circo errata.';return;}if(login==='limited'){$('#unlockerror').textContent='Troppi tentativi. Riprova tra qualche minuto.';return;}if(login!=='ok'&&!(login==='offline'&&localStorage.getItem('cc-vault'))){$('#unlockerror').textContent=login==='offline'?'Serve la connessione per il primo accesso.':'Il server non risponde. Riprova tra poco.';return;}if(login==='ok')await loadPlatform();envelope=JSON.parse(localStorage.getItem('cc-vault')||'null')||await firstEnvelope(password);key=await derive(password,envelope.salt);state=validState(await decrypt(envelope,key));localStorage.setItem('cc-vault',JSON.stringify(envelope));if($('#remember').checked)localStorage.setItem('cc-key',b64(await crypto.subtle.exportKey('raw',key)));current=state.groups[0].id;render();navigator.storage?.persist?.();}catch(err){$('#unlockerror').textContent='Password errata o archivio non leggibile.';}finally{b.disabled=false;}};}
// The circus password opens both the site (server cookie) and the encrypted archive.
async function clubLogin(password){try{const r=await fetch('/api/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});if(r.ok)return 'ok';if(r.status===401)return 'wrong';if(r.status===429)return 'limited';return 'error';}catch{return 'offline';}}
// First access on a device: shared sheet, then optional seed.clown, otherwise a new empty circus.
async function firstEnvelope(password){if(settings.url){try{const r=await requestRemote('GET');if(r.envelope){revision=r.revision;localStorage.setItem('cc-revision',revision);return r.envelope;}}catch{}}try{const r=await fetch('./seed.clown');if(r.ok)return await r.json();}catch{}const salt=b64(crypto.getRandomValues(new Uint8Array(16)));return seal({version:1,groups:[{id:uid(),name:'Il nostro circo',emoji:'🎪',members:[{id:'m1',name:'Doriano'},{id:'m2',name:'Amico'}],expenses:[],events:[],posts:[]}]},await derive(password,salt),salt);}
function navHtml(){return [['home','home','Panoramica'],['expenses','wallet','Spese'],['events','calendar','Appello'],['clown','clown','Il circo'],['settings','settings','Impostazioni']].map(([id,i,t])=>`<button data-view="${id}" class="${view===id?'active':''}">${icon(i)}<span>${t}</span></button>`).join('');}
function render(){if(!state)return;if(view==='admin'&&!isDoriano())view='settings';const g=group();current=g.id;const myself=g.members.find(m=>m.id===me)||active()[0]||g.members[0];me=myself.id;localStorage.setItem('cc-me',me);$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><span class="brandmark">♧</span> clown club</div><nav class="nav">${navHtml()}</nav><section class="groups"><div class="eyebrow">I tuoi circhi</div>${state.groups.map(x=>`<button class="groupbtn ${x.id===g.id?'active':''}" data-group="${x.id}"><span class="groupdot">${esc(x.emoji)}</span><span>${esc(x.name)}</span></button>`).join('')}<button class="groupbtn textbtn" data-action="newgroup">＋ Nuovo gruppo</button></section><div class="sidefoot">${avatar(myself)}<div><strong>${esc(short(myself.name))}</strong><div class="small muted" style="margin-top:4px">Clown verificato</div></div><button class="textbtn" data-action="profile" aria-label="Scegli profilo">⌄</button></div></aside><main class="main"><header class="topbar"><span class="crumb">Il tuo spazio &nbsp; / &nbsp; <strong>${esc(g.name)}</strong></span><div class="mobilegroups"><select id="mobilegroup" aria-label="Gruppo">${state.groups.map(x=>`<option value="${x.id}" ${x.id===g.id?'selected':''}>${esc(x.emoji+' '+x.name)}</option>`).join('')}<option value="new">＋ Nuovo gruppo</option></select></div><div class="tools"><span class="status" id="syncstatus">${settings.url?(dirty?'Da sincronizzare':'Sheets collegato'):'Sul dispositivo'}</span><button class="icon theme-toggle" data-action="theme" aria-label="Attiva modalità scura">☾</button><button class="icon" data-action="sync" aria-label="Sincronizza">${icon('sync')}</button><button class="icon" data-action="profile" aria-label="Scegli chi sei">${avatar(myself)}</button></div></header><div id="page">${view==='home'?home():view==='expenses'?expensesPage():view==='events'?eventsPage():view==='clown'?clownPage():view==='admin'?adminPage():settingsPage()}</div><footer class="footer">CLOWN CLUB &nbsp; · &nbsp; AMICIZIE IN ATTIVO, CONTI IN PARI.</footer></main></div>`;bind();applyTheme();}
function heading(title,sub,action='expense',label='Nuova spesa'){return `<div class="heading"><div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>${action?`<button class="primary" data-action="${action}">${action==='adminlock'?'':'＋ '}${esc(label)}</button>`:''}</div>`;}
function expenseList(items){let last='';return items.map(e=>{const date=e.date!==last?`<div class="dateheader">${new Date(e.date+'T12:00:00').toLocaleDateString('it-IT',{day:'numeric',month:'long',year:'numeric'})}</div>`:'';last=e.date;const payers=Object.entries(e.net).filter(([,v])=>v>0).map(([id])=>short(member(id))).join(', ');return `${date}<button class="expense" style="width:100%;text-align:left" data-expense="${e.id}"><span class="expenseicon">${e.payment?'↗':e.category==='Ristorante'?'🍝':e.category==='Alcolici'?'🍸':e.category==='Trasporti'?'🚗':'☕'}</span><span class="expbody"><strong>${esc(e.title)}</strong><p>${e.payment?'Rimborso registrato':esc(payers||'Spesa condivisa')+' ha anticipato'}${e.note?' · Con nota':''}</p></span><span class="amount">${money(e.amount)}</span></button>`;}).join('')||'<div class="empty">Nessuna spesa.<br>Il portafoglio ringrazia, per ora.</div>';}
function stats(){const g=group(),exp=g.expenses.filter(e=>!e.payment),total=exp.reduce((s,e)=>s+e.amount,0),b=balances(g)[me]||0,days=new Set(exp.map(e=>e.date)).size;return `<div class="cards"><section class="card stat purple"><div class="statlabel">◈ &nbsp; Spese del gruppo</div><div class="value">${money(total)}</div><div class="small">${exp.length} spese · dal ${exp.length?exp.map(e=>e.date).sort()[0].slice(0,4):today().slice(0,4)}</div></section><section class="card stat mint"><div class="statlabel">↗ &nbsp; ${b>=0?'Devi ricevere':'Devi restituire'}</div><div class="value">${money(Math.abs(b))}</div><div class="small">${b>=0?'Il gruppo ti deve un favore. E dei soldi.':'Il POS non è una leggenda metropolitana.'}</div></section><section class="card stat peach"><div class="statlabel">☕ &nbsp; Giorni insieme</div><div class="value">${days}</div><div class="small">Un patrimonio di caffè e cattive decisioni.</div></section></div>`;}
function home(){const g=group(),b=balances(g),exp=[...g.expenses].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6);return `${heading('Belli i conti. Meno voi.','Un altro giorno, un altro caffè da dividere.')}${installPrompt?'<div class="install"><span>Il circo sta meglio sulla tua Home.</span><button class="textbtn" data-action="install">Installa app ↗</button></div>':''}<div class="attendance-shortcut"><span>Qualcuno ha bidonato?</span><button class="secondary" data-action="absence">👻 Segna assenza</button><button class="textbtn" data-view="events">Apri l’appello ↗</button></div>${stats()}<div class="contentgrid"><section class="card"><div class="panelhead"><h2>Ultimi danni</h2><button class="textbtn" data-view="expenses">Tutte le spese ↗</button></div>${expenseList(exp)}</section><div class="rightstack"><section class="card"><div class="panelhead"><h2>Chi deve a chi</h2><button class="textbtn" data-action="settle">Regola ↗</button></div>${g.members.map((m,i)=>`<div class="memberrow">${avatar(m,i)}<div class="details"><strong class="small">${esc(short(m.name))}</strong><div class="small muted" style="margin-top:3px">${b[m.id]>0?'Deve ricevere':b[m.id]<0?'Deve restituire':'Siamo pari'}</div></div><strong class="small ${b[m.id]>=0?'positive':'negative'}">${b[m.id]>0?'+':''}${money(b[m.id]||0)}</strong></div>`).join('')}</section><section class="card clowncard"><span class="badge">IL TRIBUNALE DEL CIRCO</span><div class="clownhero">🤡</div><h2>Amici, ma con le prove.</h2><p>Alibi, bidoni e dichiarazioni discutibili.<br>Qui tutto può essere usato contro di voi.</p><button class="textbtn" style="margin-top:20px" data-view="clown">Apri il fascicolo ↗</button></section></div></div>`;}
function expensesPage(){const g=group();return `${heading('Il libro dei danni.','Ogni centesimo ha una storia imbarazzante.')}<section class="card"><div class="panelhead"><h2>Movimenti</h2><button class="textbtn" data-action="settle">Registra rimborso ↗</button></div><div class="search"><input id="search" type="search" placeholder="Cerca una spesa, una nota, un colpevole…" value="${esc(query)}" aria-label="Cerca spese"></div><div id="expense-results">${filteredExpenses()}</div></section>`;}
function filteredExpenses(){const all=[...group().expenses].filter(e=>(e.title+' '+e.note+' '+e.date+' '+Object.entries(e.net).filter(([,v])=>v>0).map(([id])=>member(id)).join(' ')).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));return expenseList(all.slice(0,limit))+(all.length>limit?'<button class="secondary loadmore" data-action="more">Mostra altre 30</button>':'');}
function expenseForm(id=null){if(stale||syncing)return toast('Attendi la sincronizzazione o ricarica la scheda.');const g=group(),old=g.expenses.find(e=>e.id===id);if(old?.imported){showModal('Movimento importato',`<p class="notice">I saldi originali Splitwise sono conservati esattamente. La quota personale di chi ha pagato non è sempre ricostruibile. Puoi modificare la nota o eliminare il movimento.</p><form><label>Nota libera</label><textarea name="note" maxlength="2000">${esc(old.note)}</textarea><div class="formactions"><button class="primary" type="submit">Salva nota</button></div></form>`,async fd=>{old.note=fd.get('note').trim();await commit('Nota salvata');});return;}showModal(old?'Modifica spesa':'Chi si è sacrificato?',`<form><label for="title">Cosa avete combinato?</label><input id="title" name="title" maxlength="160" value="${esc(old?.title||'')}" placeholder="Caffè dal gusto di rimpianto" required><div class="formrow"><div><label>Importo (€)</label><input name="amount" type="number" min="0.01" max="999999" step="0.01" value="${old?old.amount/100:''}" placeholder="0,00" required></div><div><label>Data</label><input name="date" type="date" value="${old?.date||today()}" required></div></div><label>Chi ha pagato?</label><select name="payer">${g.members.map(m=>`<option value="${m.id}" ${(old?.payer||me)===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select><label>Dividi tra</label><div class="checks">${g.members.filter(m=>!m.archived||old?.participants.includes(m.id)).map(m=>`<label><input type="checkbox" name="participants" value="${m.id}" ${(!old||old.participants.includes(m.id))?'checked':''}>${esc(short(m.name))}</label>`).join('')}</div><label>Divisione</label><select name="mode" id="splitmode"><option value="equal">In parti uguali</option><option value="custom" ${old?.custom?'selected':''}>Importi personalizzati</option></select><div id="customshares" class="${old?.custom?'':'hidden'}">${g.members.map(m=>`<label class="checkline">${esc(short(m.name))}<input type="number" name="share_${m.id}" min="0" step="0.01" placeholder="0,00" value="${old?.shares?.[m.id]!==undefined?old.shares[m.id]/100:''}" aria-label="Quota ${esc(m.name)}"></label>`).join('')}<p class="subtle">Inserisci solo le quote dei partecipanti selezionati. La somma deve coincidere con il totale.</p></div><label>Categoria</label><select name="category">${['Caffè','Ristorante','Alcolici','Trasporti','Viaggio','Casa','Altro'].map(c=>`<option ${old?.category===c?'selected':''}>${c}</option>`).join('')}</select><label>Nota, dichiarazione o insulto motivato</label><textarea name="note" maxlength="2000" placeholder="Qui si annotano i fatti. Anche quelli poco dignitosi.">${esc(old?.note||'')}</textarea><div class="formactions"><button class="primary" type="submit">${old?'Salva modifiche':'Segna il danno'}</button></div></form>`,async fd=>{const amount=Math.round(Number(fd.get('amount'))*100),ids=fd.getAll('participants');if(!ids.length)throw Error('Seleziona almeno un partecipante');let shares;if(fd.get('mode')==='custom'){shares=Object.fromEntries(ids.map(id=>[id,Math.round(Number(fd.get('share_'+id)||0)*100)]));if(Object.values(shares).some(v=>!Number.isSafeInteger(v)||v<0))throw Error('Quote non valide');}else shares=split(amount,ids);const net=ledger(amount,fd.get('payer'),shares);const e={id:old?.id||uid(),title:fd.get('title').trim(),date:fd.get('date'),amount,category:fd.get('category'),payer:fd.get('payer'),net,shares,participants:ids,note:fd.get('note').trim(),custom:fd.get('mode')==='custom',reactions:old?.reactions||{}};if(!e.title)throw Error('Scrivi una descrizione');if(old)g.expenses[g.expenses.indexOf(old)]=e;else g.expenses.push(e);await commit(old?'Spesa aggiornata':'Danno contabilizzato. Amicizia invariata, forse.');});$('#splitmode').onchange=e=>$('#customshares').classList.toggle('hidden',e.target.value!=='custom');}
function expenseDetail(id){const e=group().expenses.find(x=>x.id===id);if(!e)return;showModal(e.title,`<div class="value" style="font:800 32px Manrope;margin:20px 0">${money(e.amount)}</div><p class="muted small">${esc(e.date)} · ${esc(e.category)}${e.imported?' · Importata da Splitwise':''}</p>${e.note?`<p class="notice note">${esc(e.note)}</p>`:''}<h3 style="margin-top:23px">Impatto sui saldi</h3>${Object.entries(e.net).filter(([,v])=>v!==0).map(([id,v])=>`<div class="memberrow"><span class="grow">${esc(member(id))}</span><strong class="${v>0?'positive':'negative'}">${v>0?'+':''}${money(v)}</strong></div>`).join('')}<p class="subtle" style="margin:17px 0">Positivo = credito aggiunto, negativo = debito aggiunto.${e.imported?' La presenza è dedotta dagli importi diversi da zero.':''}</p><div id="detailreactions">${reactionHtml(e)}</div><div class="formactions"><button class="secondary danger" id="deleteexpense">Elimina</button>${!e.payment?'<button class="primary" id="editexpense">Modifica</button>':''}</div>`);bindReactions(e,'expense');$('#deleteexpense').onclick=()=>{if(confirm('Eliminare questa spesa? Cambieranno i saldi del gruppo.')){group().expenses=group().expenses.filter(x=>x.id!==id);$('#modal').close();commit('Movimento eliminato');}};if($('#editexpense'))$('#editexpense').onclick=()=>{$('#modal').close();expenseForm(id);};}
function reactionHtml(x){return ['🤡','💀','🪦'].map(em=>`<button class="react ${(x.reactions?.[em]||[]).includes(me)?'on':''}" data-react="${em}">${em} ${(x.reactions?.[em]||[]).length||''}</button>`).join('');}
function bindReactions(x,type){$('#modal').querySelectorAll('[data-react]').forEach(b=>b.onclick=async()=>{x.reactions||={};const em=b.dataset.react,arr=x.reactions[em]||[];x.reactions[em]=arr.includes(me)?arr.filter(i=>i!==me):[...arr,me];await persist();$('#detailreactions').innerHTML=reactionHtml(x);bindReactions(x,type);if(settings.url)sync().catch(e=>toast(e.message));});}
function settleForm(from='',to='',amount=''){const g=group(),s=settlements(g),residual=Object.values(balances(g)).reduce((a,b)=>a+b,0);showModal('Pareggiamo i conti',`<p class="notice">Registra un pagamento già effettuato. L’app non trasferisce denaro.</p>${residual?`<p class="notice">I saldi importati hanno uno scarto di ${money(residual)}. I rimborsi proposti coprono solo gli importi abbinabili.</p>`:''}${s.length?`<h3>Per chiudere i conti</h3>${s.map(t=>`<div class="memberrow"><span class="grow small">${esc(short(member(t.from)))} → ${esc(short(member(t.to)))}</span><strong class="small">${money(t.amount)}</strong></div>`).join('')}`:'<p class="muted">Nessun debito da pareggiare.</p>'}<form><label>Da chi</label><select name="from">${g.members.map(m=>`<option value="${m.id}" ${(from||s[0]?.from||me)===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select><label>A chi</label><select name="to">${g.members.map(m=>`<option value="${m.id}" ${(to||s[0]?.to||g.members.find(m=>m.id!==me)?.id)===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select><div class="formrow"><div><label>Importo (€)</label><input name="amount" type="number" step="0.01" min="0.01" value="${amount||(s[0]?s[0].amount/100:'')}" required></div><div><label>Data</label><input name="date" type="date" value="${today()}" required></div></div><div class="formactions"><button class="primary" type="submit">Registra rimborso</button></div></form>`,async fd=>{const from=fd.get('from'),to=fd.get('to'),n=Math.round(Number(fd.get('amount'))*100);if(from===to)throw Error('Non puoi rimborsare te stesso. Bel tentativo.');if(!Number.isSafeInteger(n)||n<=0)throw Error('Importo non valido');g.expenses.push({id:uid(),title:short(member(from))+' ha rimborsato '+short(member(to)),amount:n,date:fd.get('date'),category:'Pagamento',payment:true,net:{[from]:n,[to]:-n},participants:[],note:'',reactions:{}});await commit('Rimborso registrato. Questo momento entrerà nella storia.');});}
function eventsPage(){const g=group();return `${heading('Presenze e assenze.','Scegli una persona e segna come è andata.','absence','Segna assenza')}<div class="attendance-guide"><div><strong>Segna un’assenza in pochi secondi</strong><p>Premi “Segna assenza”, scegli persona e giorno e salva. Non serve creare prima un’uscita.</p></div><button class="secondary" data-action="event">＋ Organizza un’uscita</button></div><div class="twocol">${[...g.events].sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<section class="card event"><div class="eventtop"><div><div class="eyebrow">${esc(e.date)}</div><h2 style="margin-top:9px">${esc(e.title)}</h2></div><span class="groupdot">🗓</span></div>${e.note?`<p class="note muted small" style="margin-top:12px">${esc(e.note)}</p>`:''}<div class="attendance-list">${g.members.filter(m=>!m.archived||e.rsvp[m.id]).map(m=>`<div class="attendee"><div class="attendee-name"><strong>${esc(short(m.name))}</strong><span class="small muted">${({yes:'Presente',no:'Assente',late:'In ritardo'})[e.rsvp[m.id]?.status]||'Da confermare'}</span></div><div class="attendance-options" role="group" aria-label="Presenza di ${esc(m.name)}">${[['yes','Presente'],['no','Assente'],['late','In ritardo']].map(([status,label])=>`<button class="attendance-option ${status} ${e.rsvp[m.id]?.status===status?'selected':''}" data-attendance="${status}" data-event="${e.id}" data-person="${m.id}" aria-pressed="${e.rsvp[m.id]?.status===status}">${label}</button>`).join('')}</div>${e.rsvp[m.id]?.reason?`<p class="attendance-reason">${esc(e.rsvp[m.id].reason)}</p>`:''}</div>`).join('')}</div><p class="subtle">Tocca lo stato già selezionato per tornare a “Da confermare”.</p><div class="panelhead" style="margin:16px 0 0"><button class="textbtn" data-rsvp="${e.id}">Aggiungi alibi o nota ↗</button><button class="delete" data-deleteevent="${e.id}">Elimina uscita</button></div></section>`).join('')||'<div class="card empty"><h3>Nessuna presenza ancora segnata</h3><p>Qualcuno non si è fatto vedere?<br>Usa “Segna assenza” qui sopra, anche per una data passata.</p></div>'}</div><section class="card" style="margin-top:20px"><div class="panelhead"><h2>Presenze storiche dalle spese</h2><span class="badge">DEDOTTE</span></div><p class="subtle">Una presenza per persona e giorno con spese. Le assenze si segnano esplicitamente con i pulsanti qui sopra.</p><div class="scrolltable"><table><thead><tr><th>PERSONA</th><th>GIORNI CON SPESE</th><th>ASSENZE SEGNATE</th></tr></thead><tbody>${presenceStats().sort((a,b)=>b.days-a.days).map(m=>`<tr><td>${esc(m.name)}</td><td>${m.days}</td><td>${m.absences}</td></tr>`).join('')}</tbody></table></div></section>`;}
function absenceForm(){showModal('Segna un’assenza',`<form><p class="muted small">Scegli chi non c’era e in quale giorno. L’alibi è facoltativo.</p><label for="absentmember">Chi era assente?</label><select id="absentmember" name="member">${active().map(m=>`<option value="${m.id}" ${m.id===me?'selected':''}>${esc(m.name)}</option>`).join('')}</select><label for="absentdate">In quale giorno?</label><input id="absentdate" type="date" name="date" value="${today()}" required><label for="absentreason">Alibi o nota</label><textarea id="absentreason" name="reason" maxlength="400" placeholder="«Arrivo» non conta come presenza."></textarea><div class="formactions"><button class="primary" type="submit">Salva assenza</button></div></form>`,async fd=>{recordAbsence(group(),fd.get('member'),fd.get('date'),fd.get('reason'),me,uid());view='events';await commit('Assenza segnata. Il bidone è agli atti.');});}
function eventForm(){showModal('Convoca il circo',`<form><label>Nome uscita</label><input name="title" maxlength="120" placeholder="Caffè e promesse non mantenute" required><label>Data</label><input type="date" name="date" value="${today()}" required><label>Luogo, orario o messaggio al gruppo</label><textarea name="note" maxlength="2000" placeholder="Alle 10. Vere. Non le vostre."></textarea><div class="formactions"><button class="primary" type="submit">Convoca i clown</button></div></form>`,async fd=>{const title=fd.get('title').trim();if(!title)throw Error('Scrivi un titolo');group().events.push({id:uid(),title,date:fd.get('date'),note:fd.get('note').trim(),rsvp:{}});await commit('Convocazione agli atti');});}
function rsvpForm(id){const e=group().events.find(x=>x.id===id);showModal('Mettiamolo a verbale',`<form><p class="muted small">${esc(e.title)} · ${esc(e.date)}</p><label>Chi?</label><select name="member" id="rsvpmember">${group().members.map(m=>`<option value="${m.id}" ${m.id===me?'selected':''}>${esc(m.name)}</option>`).join('')}</select><label>Verdetto</label><select name="status" id="rsvpstatus"><option value="yes">🟢 Presente — evento raro</option><option value="no">👻 Assente — che sorpresa</option><option value="late">⏳ In ritardo — il tempo è relativo</option><option value="unknown">⚪ Da confermare</option></select><label>L’alibi / nota libera</label><textarea name="reason" id="rsvpreason" maxlength="400" placeholder="«Mi sono addormentato» è già agli atti."></textarea><button type="button" class="textbtn" id="alibi" style="margin-top:10px">🎲 Genera un alibi discutibile</button><div class="formactions"><button class="primary" type="submit">A verbale</button></div></form>`,async fd=>{const id=fd.get('member');if(fd.get('status')==='unknown')delete e.rsvp[id];else e.rsvp[id]={status:fd.get('status'),reason:fd.get('reason').trim(),by:me};await commit('Appello aggiornato');});const fill=()=>{const r=e.rsvp[$('#rsvpmember').value];$('#rsvpstatus').value=r?.status||'unknown';$('#rsvpreason').value=r?.reason||'';};fill();$('#rsvpmember').onchange=fill;$('#alibi').onclick=()=>{$('#rsvpreason').value=['Devo supervisionare il caricamento del telefono.','Sono già uscito, ma spiritualmente.','Il divano mi ha riconosciuto come suo erede.','Ho un impegno con la mia indisponibilità.','Arrivo tra cinque minuti, in un altro fuso orario.'][Math.floor(Math.random()*5)];};}
function presenceStats(){const g=group();return g.members.map(m=>{const ds=[...new Set(g.expenses.filter(e=>!e.payment&&e.participants.includes(m.id)).map(e=>e.date))].sort();return {...m,days:ds.length,last:ds.at(-1),absences:g.events.filter(e=>e.rsvp[m.id]?.status==='no').length,lates:g.events.filter(e=>e.rsvp[m.id]?.status==='late').length,yes:g.events.filter(e=>e.rsvp[m.id]?.status==='yes').length};});}
function clownPage(){const g=group(),ps=presenceStats().filter(m=>!m.archived),rank=[...ps].sort((a,b)=>rankMode==='absence'?b.absences-a.absences:b.days-a.days),top=rank[0],hasAbs=ps.some(m=>m.absences),b=balances(g),sponsor=[...g.members].sort((a,c)=>(b[c.id]||0)-(b[a.id]||0))[0];return `${heading('Benvenuti al circo.','Le spese passano. Le figure di merda restano.','post','Nuovo sfottò')}<div class="contentgrid"><section class="card"><div class="panelhead"><h2>La bacheca dei verbali</h2><span class="badge">${g.posts.length} PROVE</span></div>${[...g.posts].reverse().map(p=>`<article class="post"><div class="inlinegroup">${avatar(g.members.find(m=>m.id===p.author)||{name:'Ex membro'})}<div class="grow"><strong class="small">${esc(short(member(p.author)))}</strong><div class="small muted">${esc(p.date)}${p.target?' · A carico di '+esc(short(member(p.target))):''}</div></div><button class="delete" data-deletepost="${p.id}">Elimina</button></div><p>${esc(p.text)}</p><div>${['🤡','💀','🪦'].map(em=>`<button class="react ${(p.reactions?.[em]||[]).includes(me)?'on':''}" data-postreact="${p.id}" data-emoji="${em}">${em} ${(p.reactions?.[em]||[]).length||''}</button>`).join('')}</div></article>`).join('')||'<div class="empty">Il verbale è ancora pulito.<br>Improbabile che duri.</div>'}</section><div class="rightstack"><section class="card"><div class="panelhead"><h2>La classifica</h2><span>🏆</span></div><div class="tabs"><button data-rank="presence" class="${rankMode==='presence'?'active':''}">Gli habitué</button><button data-rank="absence" class="${rankMode==='absence'?'active':''}">I bidonisti</button></div>${rank.map((m,i)=>{const n=rankMode==='absence'?m.absences:m.days,max=rankMode==='absence'?Math.max(...ps.map(m=>m.absences),1):Math.max(...ps.map(m=>m.days),1);return `<div class="ranking"><span class="rank">${String(i+1).padStart(2,'0')}</span><div class="grow"><strong class="small">${esc(short(m.name))}</strong><div class="bar"><i style="width:${n/max*100}%"></i></div></div><span class="small muted">${n} ${rankMode==='absence'?'bidoni':'giorni'}</span></div>`;}).join('')}<p class="subtle" style="margin-top:15px">${rankMode==='absence'?'Solo assenze segnate nell’Appello. Nessuna condanna per supposizione.':'Giorni distinti con partecipazione a spese. Non include gli RSVP.'}</p></section><section class="card clowncard"><span class="badge">${hasAbs?'FANTASMA CERTIFICATO':'IL FINANZIATORE DEL CIRCO'}</span><div class="clownhero">${hasAbs?'👻':'💸'}</div><h2>${esc(short(hasAbs?[...ps].sort((a,b)=>b.absences-a.absences)[0].name:sponsor.name))}</h2><p>${hasAbs?'Si vede più spesso il suo nome negli alibi che la sua faccia al bar.':(b[sponsor.id]>0?'Ha il credito più alto del gruppo. Praticamente una banca, con amici peggiori.':'Conti in pari. Il talento per sparire resta fuori bilancio.')}</p></section></div></div>`;}
function postForm(){showModal('Nuovo verbale del circo',`<form><label>A carico di</label><select name="target"><option value="">Tutto il circo</option>${group().members.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select><label>La dichiarazione</label><textarea name="text" maxlength="2000" required placeholder="Fatti, accuse, citazioni che andavano dimenticate."></textarea><button class="textbtn" type="button" id="roastgen" style="margin-top:12px">🎲 Prepara un capo d’accusa</button><div class="formactions"><button class="primary" type="submit">Metti agli atti</button></div></form>`,async fd=>{const text=fd.get('text').trim();if(!text)throw Error('Scrivi almeno una prova a carico');group().posts.push({id:uid(),author:me,target:fd.get('target'),text,date:today(),reactions:{}});await commit('Il tribunale ha acquisito la prova');});$('#roastgen').onclick=()=>{$('#modal textarea').value=['Presente quando si ordina. Irreperibile quando arriva il conto.','Ha detto «arrivo». La data di riferimento resta da definire.','Il suo portafoglio è patrimonio UNESCO: nessuno può toccarlo.','L’unico investimento a lungo termine è il debito col gruppo.','Non è in ritardo: è la versione beta di una presenza.'][Math.floor(Math.random()*5)];};}
function settingsPage(){return `${heading('Dietro le quinte.','Le cose serie, nel posto meno serio.',null)}<div class="twocol"><section class="card settingsblock"><h2>Aspetto</h2><p>Scegli il tema. La preferenza resta salvata su questo dispositivo.</p><label for="themechoice">Modalità</label><select id="themechoice"><option value="auto" ${(localStorage.getItem('cc-theme')||'auto')==='auto'?'selected':''}>Automatica · segui il dispositivo</option><option value="light" ${localStorage.getItem('cc-theme')==='light'?'selected':''}>Chiara</option><option value="dark" ${localStorage.getItem('cc-theme')==='dark'?'selected':''}>Scura</option></select></section><section class="card settingsblock"><h2>Il tuo gruppo</h2><p>Scegli chi sei: firme, reazioni e saldi seguiranno questo profilo. È un’identità condivisa di fiducia, senza account individuali.</p><button class="secondary" data-action="profile">Sono ${esc(short(member(me)))} ⌄</button><button class="textbtn" data-action="newgroup" style="margin-left:12px">＋ Nuovo gruppo</button><label>Nome del gruppo</label><input id="groupname" value="${esc(group().name)}" maxlength="80"><button class="textbtn" data-action="rename" style="margin-top:12px">Salva nome</button>${state.groups.length>1?'<button class="textbtn danger" data-action="deletegroup" style="margin:12px 0 0 12px">Elimina gruppo</button>':''}<div style="margin-top:20px">${group().members.map(m=>`<div class="memberrow"><span class="grow small">${esc(m.name)}</span><button class="textbtn" data-archive="${m.id}">${m.archived?'Riattiva':'Archivia'}</button></div>`).join('')}</div><button class="secondary" data-action="member" style="margin-top:20px">＋ Aggiungi amico discutibile</button></section>${notificationCard()}${isDoriano()?`<section class="card settingsblock"><h2>Area Doriano</h2><p>Configurazione Google Sheets e notifiche a tutto il circo. Accesso riservato e protetto da password.</p><button class="primary" data-action="admin">${adminUnlocked?'Apri area Doriano':'Sblocca area Doriano'}</button></section>`:''}<section class="card settingsblock"><h2>Archivio e backup</h2><p>Esporta l’intero circo in un backup cifrato. Un CSV Splitwise crea un nuovo gruppo conservando esattamente i saldi originali.</p><button class="secondary" data-action="backup">Scarica backup cifrato</button><label class="secondary filebutton" style="display:inline-block;margin-top:12px">Importa backup .clown<input id="restore" type="file" accept=".clown,application/json"></label><label class="secondary filebutton" style="display:inline-block;margin-top:12px">Importa CSV Splitwise<input id="csvimport" type="file" accept=".csv,text/csv"></label><p class="subtle">Import iniziale: 528 spese e 4 rimborsi dal tuo CSV del 18 ottobre 2026. Le quote originali non vengono ricalcolate.</p></section><section class="card settingsblock"><h2>Accesso e installazione</h2><p>L’archivio è cifrato con AES-GCM. Se hai scelto “Ricordami”, la chiave resta su questo dispositivo finché non esci o cancelli i dati del browser.</p><button class="secondary" data-action="password">Cambia password</button><button class="textbtn danger" data-action="lock" style="margin-left:15px">Esci dal dispositivo</button><div class="notice">Su iPhone: Safari → Condividi → Aggiungi alla schermata Home. Su Android: menu Chrome → Installa app. La PWA funziona offline dopo il primo caricamento.</div><p class="subtle">Chi usa il dispositivo sbloccato può accedere al circo. Conserva un backup e la password: non esiste recupero password.</p></section></div>`;}
function profile(){showModal('Chi è entrato nel circo?',`<div style="margin-top:20px">${group().members.map((m,i)=>`<button class="groupbtn" data-profile="${m.id}">${avatar(m,i)}<span>${esc(m.name)}</span>${me===m.id?'<span class="badge">TU</span>':''}</button>`).join('')}</div>`);$('#modal').querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{me=b.dataset.profile;localStorage.setItem('cc-me',me);$('#modal').close();render();});}
function groupForm(){showModal('Un altro circo?',`<form><label>Nome del gruppo</label><input name="name" maxlength="80" placeholder="I soliti sospetti" required><label>Amici (uno per riga)</label><textarea name="members" required placeholder="Doriano&#10;Alessandro&#10;Antonio"></textarea><div class="formactions"><button class="primary" type="submit">Apri il tendone</button></div></form>`,async fd=>{const names=[...new Set(fd.get('members').split('\n').map(x=>x.trim()).filter(Boolean))];if(names.length<2||names.length>50)throw Error('Inserisci da 2 a 50 nomi diversi');const name=fd.get('name').trim();if(!name)throw Error('Scrivi il nome del gruppo');const g={id:uid(),name,emoji:'🎪',members:names.map(name=>({id:uid(),name})),expenses:[],events:[],posts:[]};state.groups.push(g);current=g.id;me=g.members[0].id;await commit('Tendone aperto');});}
async function requestRemote(method,payload){const r=await api('/api/sync',{method,...(method==='POST'?{body:payload}:{} )});if(!r.ok&&!r.conflict)throw Error(r.error||'Google Sheets non disponibile');return r;}
async function useRemote(remote){const k=await deriveViaPrompt(remote.envelope);const data=validState(await decrypt(remote.envelope,k));key=k;state=data;envelope=remote.envelope;revision=remote.revision;dirty=false;localStorage.setItem('cc-vault',JSON.stringify(envelope));localStorage.setItem('cc-key',b64(await crypto.subtle.exportKey('raw',key)));localStorage.setItem('cc-revision',revision);localStorage.setItem('cc-dirty','0');current=state.groups[0].id;render();}
async function deriveViaPrompt(e){try{await decrypt(e,key);return key;}catch{const pw=prompt('Password del circo condiviso (potrebbe essere diversa da quella locale):');if(!pw)throw Error('Sincronizzazione annullata');const k=await derive(pw,e.salt);try{await decrypt(e,k);}catch{throw Error('Password del circo condiviso errata');}return k;}}
function conflict(remote){showModal('Due versioni del circo',`<p class="notice">Questo dispositivo e il foglio hanno modifiche diverse. Per evitare perdite, il caricamento è stato fermato. Scarica prima il backup locale, poi scegli se caricare la versione del foglio.</p><div class="formactions"><button class="secondary" id="confbackup">Backup locale</button><button class="primary" id="confpull">Carica dal foglio</button></div>`);$('#confbackup').onclick=backup;$('#confpull').onclick=async()=>{if(!confirm('Sostituire i dati locali con quelli del foglio? Salva prima il backup.'))return;try{await useRemote(remote);$('#modal').close();toast('Versione condivisa caricata');}catch(e){toast(e.message);}};}
async function sync(){if(syncing)return;if(!settings.url){view='settings';render();toast('Collega il foglio da Impostazioni');return;}if(!navigator.onLine){toast('Sei offline. Le modifiche restano salvate qui.');return;}syncing=true;let sentEnvelope;let syncChanges;if($('#syncstatus'))$('#syncstatus').textContent='Sincronizzo…';try{await saving;sentEnvelope=envelope;syncChanges=changes;const remote=await requestRemote('GET');if(syncChanges!==changes){toast('Nuove modifiche locali: premi di nuovo Sincronizza.');return;}if(remote.envelope){if(dirty&&remote.revision!==revision){conflict(remote);return;}if(!dirty){if(remote.revision!==revision||remote.envelope.cipher!==envelope.cipher)await useRemote(remote);}else{const r=await requestRemote('POST',{expectedRevision:revision,envelope:sentEnvelope});if(r.conflict){conflict(await requestRemote('GET'));return;}await saving;revision=r.revision;dirty=envelope.cipher!==sentEnvelope.cipher;}}else{const r=await requestRemote('POST',{expectedRevision:0,envelope:sentEnvelope});if(r.conflict){conflict(await requestRemote('GET'));return;}await saving;revision=r.revision;dirty=envelope.cipher!==sentEnvelope.cipher;}localStorage.setItem('cc-revision',revision);localStorage.setItem('cc-dirty',dirty?'1':'0');localStorage.setItem('cc-lastsync',new Date().toLocaleString('it-IT'));if(view==='settings')render();toast('Il circo è sincronizzato');}catch(e){toast('Sync non riuscita. Dati locali conservati. '+e.message);}finally{syncing=false;if($('#syncstatus'))$('#syncstatus').textContent=dirty?'Da sincronizzare':'Sheets collegato';}}
function passwordForm(){showModal('Cambia la parola d’ordine',`<form><p class="notice">Condividi la nuova password con gli amici e aggiorna anche CLUB_PASSWORD su Vercel, altrimenti nessuno potrà più entrare. Gli altri dispositivi dovranno ricaricare la versione del foglio e usare la nuova password. Conserva separatamente la password dei vecchi backup.</p><label>Nuova password</label><input type="password" name="password" minlength="12" autocomplete="new-password" required><label>Ripeti password</label><input type="password" name="repeat" minlength="12" autocomplete="new-password" required><div class="formactions"><button class="primary" type="submit">Aggiorna password</button></div></form>`,async fd=>{if(fd.get('password')!==fd.get('repeat'))throw Error('Le password non coincidono');const salt=b64(crypto.getRandomValues(new Uint8Array(16))),newKey=await derive(fd.get('password'),salt),newEnvelope=await encrypt(state,newKey,salt);key=newKey;envelope=newEnvelope;localStorage.setItem('cc-key',b64(await crypto.subtle.exportKey('raw',key)));await commit('Password aggiornata su questo dispositivo');});}
function bind(){if($('#broadcastform'))$('#broadcastform').onsubmit=sendBroadcast;if($('#themechoice'))$('#themechoice').onchange=e=>setTheme(e.target.value);document.querySelectorAll('[data-attendance]').forEach(b=>b.onclick=()=>{if(stale)return toast('Ricarica questa scheda prima di modificare.');const e=group().events.find(x=>x.id===b.dataset.event),id=b.dataset.person,status=b.dataset.attendance;if(e.rsvp[id]?.status===status)delete e.rsvp[id];else e.rsvp[id]={status,reason:e.rsvp[id]?.status===status?e.rsvp[id].reason:'',by:me};commit(status==='no'?'Assenza aggiornata':'Appello aggiornato');});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;limit=30;render();window.scrollTo(0,0);});document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{current=b.dataset.group;query='';render();});if($('#mobilegroup'))$('#mobilegroup').onchange=e=>{if(e.target.value==='new'){groupForm();e.target.value=current;}else{current=e.target.value;query='';render();}};const actions={admin:openAdmin,adminlock:lockAdmin,enablepush:enablePush,disablepush:disablePush,absence:absenceForm,theme:()=>{setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');if(view==='settings')render();},expense:()=>expenseForm(),event:eventForm,post:postForm,settle:()=>settleForm(),profile,newgroup:groupForm,backup,password:passwordForm,sync,more:()=>{limit+=30;$('#expense-results').innerHTML=filteredExpenses();bindExpenseButtons();},install:async()=>{installPrompt?.prompt();installPrompt=null;render();},lock:async()=>{if(adminUnlocked)await lockAdmin();await saving;localStorage.removeItem('cc-key');key=null;state=null;$('#modal').close();lockScreen();},deletegroup:async()=>{if(state.groups.length<2)return toast('Serve almeno un gruppo: rinominalo invece di eliminarlo');const g=group();if(prompt(`Eliminare «${g.name}» con ${g.expenses.length} spese? Non si può annullare (scarica prima un backup se ti serve). Per confermare scrivi il nome del gruppo:`)?.trim()!==g.name)return toast('Eliminazione annullata');state.groups=state.groups.filter(x=>x.id!==g.id);current=state.groups[0].id;await commit('Gruppo eliminato');},rename:async()=>{const n=$('#groupname').value.trim();if(!n)return toast('Scrivi un nome');group().name=n;await commit('Nome aggiornato');},member:()=>showModal('Aggiungi un clown',`<form><label>Nome</label><input name="name" maxlength="80" required><div class="formactions"><button type="submit" class="primary">Aggiungi</button></div></form>`,async fd=>{const name=fd.get('name').trim();if(!name||group().members.some(m=>m.name.toLowerCase()===name.toLowerCase()))throw Error('Nome vuoto o già presente');group().members.push({id:uid(),name});await commit('Un altro clown a bordo');}),connect:async()=>{const url=$('#sheeturl').value.trim(),token=$('#sheettoken').value.trim();await api('/api/admin/sheets',{method:'POST',body:{url,token}});localStorage.removeItem('cc-settings');settings={url:'managed'};await loadAdminData();toast('Google Sheets collegato per tutti');await sync();render();},disconnect:async()=>{if(!confirm('Scollegare Google Sheets per tutti i dispositivi? I dati restano sul foglio e sui dispositivi.'))return;await api('/api/admin/sheets',{method:'DELETE'});settings={url:''};await loadAdminData();render();toast('Foglio scollegato');}};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>Promise.resolve(actions[b.dataset.action]?.()).catch(e=>toast(e.message)));bindExpenseButtons();if($('#search'))$('#search').oninput=e=>{query=e.target.value;limit=30;$('#expense-results').innerHTML=filteredExpenses();bindExpenseButtons();};document.querySelectorAll('[data-rsvp]').forEach(b=>b.onclick=()=>rsvpForm(b.dataset.rsvp));document.querySelectorAll('[data-deleteevent]').forEach(b=>b.onclick=()=>{if(confirm('Eliminare uscita e relativo appello?')){group().events=group().events.filter(e=>e.id!==b.dataset.deleteevent);commit('Uscita eliminata');}});document.querySelectorAll('[data-rank]').forEach(b=>b.onclick=()=>{rankMode=b.dataset.rank;render();});document.querySelectorAll('[data-deletepost]').forEach(b=>b.onclick=()=>{if(confirm('Ritirare questa prova dagli atti?')){group().posts=group().posts.filter(p=>p.id!==b.dataset.deletepost);commit('Verbale eliminato');}});document.querySelectorAll('[data-postreact]').forEach(b=>b.onclick=()=>{const p=group().posts.find(p=>p.id===b.dataset.postreact);p.reactions||={};const em=b.dataset.emoji,a=p.reactions[em]||[];p.reactions[em]=a.includes(me)?a.filter(id=>id!==me):[...a,me];commit();});document.querySelectorAll('[data-archive]').forEach(b=>b.onclick=()=>{const m=group().members.find(m=>m.id===b.dataset.archive);if(!m.archived&&active().length<=1)return toast('Lascia almeno un membro attivo');m.archived=!m.archived;commit('Stato membro aggiornato');});if($('#restore'))$('#restore').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const env=JSON.parse(await f.text()),pw=prompt('Password del backup:');if(!pw)return;const k=await derive(pw,env.salt),data=validState(await decrypt(env,k));if(!confirm('Sostituire tutto l’archivio locale? Scarica prima un backup.'))return;key=k;envelope=env;state=data;current=data.groups[0].id;localStorage.setItem('cc-key',b64(await crypto.subtle.exportKey('raw',key)));await commit('Backup ripristinato');}catch(err){toast('Backup non valido o password errata');}};if($('#csvimport'))$('#csvimport').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const rows=parseCSV(await f.text()),g=importSplitwise(rows,f.name.replace(/\.csv$/i,''));if(!confirm(`Importare ${g.expenses.length} movimenti in un nuovo gruppo?`))return;state.groups.push(g);current=g.id;await commit('CSV importato senza ricalcolare i saldi');}catch(err){toast(err.message);}};}
function bindExpenseButtons(){document.querySelectorAll('[data-expense]').forEach(b=>b.onclick=()=>expenseDetail(b.dataset.expense));const more=document.querySelector('[data-action=more]');if(more)more.onclick=()=>{limit+=30;$('#expense-results').innerHTML=filteredExpenses();bindExpenseButtons();};}
document.addEventListener('click',e=>{if(syncing){e.preventDefault();e.stopImmediatePropagation();toast('Sincronizzazione in corso…');}},true);document.addEventListener('submit',e=>{if(syncing){e.preventDefault();e.stopImmediatePropagation();}},true);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;if(state)render();});window.addEventListener('online',()=>{if(state&&settings.url)sync();});window.addEventListener('storage',e=>{if(e.key==='cc-vault'&&state){stale=true;toast('Archivio aggiornato in un’altra scheda. Ricarica prima di modificarlo.');}});
async function api(path,{method='GET',body}={}){const r=await fetch(path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});let data;try{data=await r.json();}catch{throw Error('Servizio non disponibile');}if(!r.ok){if(path.startsWith('/api/admin/')&&r.status===403)adminUnlocked=false;throw Object.assign(Error(data.error||'Operazione non riuscita'),{status:r.status});}return data;}
function isDoriano(){return adminOwner&&state&&short(member(me)).toLowerCase()==='doriano';}
let needsLogin=false;
async function loadPlatform(){needsLogin=false;try{const [identity,status]=await Promise.all([api('/api/whoami'),api('/api/club/status')]);adminOwner=identity.isDoriano;settings={url:status.connected?'managed':''};if(adminOwner){try{await api('/api/admin/session');adminUnlocked=true;await loadAdminData();}catch{adminUnlocked=false;}}if('serviceWorker'in navigator&&'PushManager'in window){const reg=await navigator.serviceWorker.getRegistration();pushEnabled=!!(await reg?.pushManager.getSubscription())&&localStorage.getItem('cc-push-registered')==='1';}}catch(err){needsLogin=err.status===401;settings={url:localStorage.getItem('cc-managed-sync')==='1'?'managed':''};}localStorage.setItem('cc-managed-sync',settings.url?'1':'0');}
function notificationCard(){return `<section class="card settingsblock"><h2>Notifiche del circo</h2><p>Ricevi gli avvisi di Doriano anche quando l’app è chiusa. Devi attivarli su ogni dispositivo.</p><span class="badge ${pushEnabled?'green':''}">${pushEnabled?'Attive su questo dispositivo':'Non ancora attive'}</span><div style="margin-top:18px"><button class="${pushEnabled?'secondary':'primary'}" data-action="${pushEnabled?'disablepush':'enablepush'}">${pushEnabled?'Disattiva notifiche':'Attiva notifiche'}</button></div><p class="subtle">Su iPhone apri prima l’app dalla schermata Home. Poi premi Attiva notifiche e consenti quando te lo chiede il telefono.</p></section>`;}
async function loadAdminData(){const [sheet,subs]=await Promise.all([api('/api/admin/sheets'),api('/api/admin/subscribers')]);adminData=sheet;if(!sheet.url){try{const old=JSON.parse(localStorage.getItem('cc-settings')||'{}');if(old.url&&old.token)adminData={url:old.url,hasToken:false,token:old.token,legacy:true};}catch{}}subscriberDevices=subs.devices;}
async function openAdmin(){if(!isDoriano())return;if(adminUnlocked){try{await loadAdminData();view='admin';render();return;}catch{adminUnlocked=false;}}showModal('Area Doriano',`<form><p class="muted small">Inserisci la password per gestire Google Sheets e inviare notifiche al circo.</p><label for="adminpassword">Password area Doriano</label><input id="adminpassword" name="password" type="password" autocomplete="current-password" required><div class="formactions"><button type="submit" class="primary">Sblocca</button></div></form>`,async fd=>{await api('/api/admin/login',{method:'POST',body:{password:fd.get('password')}});adminUnlocked=true;await loadAdminData();view='admin';render();});}
async function lockAdmin(){await api('/api/admin/logout',{method:'POST'});adminUnlocked=false;adminData={url:'',hasToken:false};subscriberDevices=[];view='settings';render();toast('Area Doriano bloccata');}
function adminPage(){if(!adminUnlocked)return `${heading('Area Doriano.','Google Sheets e notifiche sono protetti.',null)}<section class="card"><button class="primary" data-action="admin">Sblocca area Doriano</button></section>`;return `${heading('Area Doriano.','La regia del circo. Solo per te.','adminlock','Blocca area')}<div class="twocol"><section class="card settingsblock"><h2>Notifica a tutti</h2><p>${subscriberDevices.length} dispositivi hanno attivato le notifiche. L’avviso arriva anche con l’app chiusa, se il sistema lo consente.</p><form id="broadcastform"><label for="pushtitle">Titolo</label><input id="pushtitle" name="title" maxlength="80" placeholder="Convocazione del circo" required><label for="pushbody">Messaggio</label><textarea id="pushbody" name="body" maxlength="500" placeholder="Caffè alle 10. Portate il portafoglio, per una volta." required></textarea><button class="primary" type="submit" style="margin-top:18px" ${subscriberDevices.length?'':'disabled'}>Invia a tutti i dispositivi</button><p class="small" id="pushreport" role="status" style="margin-top:14px"></p></form><div style="margin-top:20px">${subscriberDevices.map(d=>`<div class="memberrow"><span class="grow">${esc(d.member_name)}</span><span class="badge green">Iscritto</span></div>`).join('')||'<p class="subtle">Nessuna iscrizione. Gli amici devono premere Attiva notifiche nelle impostazioni della PWA.</p>'}</div></section><section class="card settingsblock"><h2>Google Sheets</h2><p>Questa configurazione vale per tutto il circo. URL, token e script sono accessibili solo dalla tua area protetta.</p>${adminData.legacy?'<div class="notice">Ho recuperato la configurazione precedente da questo dispositivo. Premi Salva e collega per renderla disponibile a tutti.</div>':''}${adminData.fromEnv?'<div class="notice">Il foglio è configurato nelle variabili di Vercel (SHEETS_URL e SHEETS_TOKEN). Per cambiarlo modifica lì e ripubblica.</div>':''}<label for="sheeturl">URL web app Apps Script</label><input type="url" id="sheeturl" value="${esc(adminData.url||'')}" placeholder="https://script.google.com/macros/s/…/exec"><label for="sheettoken">Token di accesso</label><input type="password" id="sheettoken" value="${esc(adminData.legacy?adminData.token:'')}" placeholder="${adminData.hasToken?'Già salvato. Lascia vuoto per mantenerlo.':'Almeno 24 caratteri'}" autocomplete="off"><div class="formactions"><button class="primary" data-action="connect">Salva e collega</button></div><div class="adminlinks"><a href="/api/admin/script">Scarica lo script Google ↗</a><a href="/api/admin/guide">Guida al collegamento ↗</a></div>${adminData.url&&!adminData.fromEnv?'<button class="textbtn danger" data-action="disconnect" style="margin-top:18px">Scollega Google Sheets per tutti</button>':''}</section></div>`;}
async function sendBroadcast(e){e.preventDefault();const title=$('#pushtitle').value.trim(),body=$('#pushbody').value.trim();if(!title||!body)return;if(!confirm(`Inviare a tutti i ${subscriberDevices.length} dispositivi iscritti?\n\n${title}\n${body}`))return;const btn=e.target.querySelector('button');btn.disabled=true;try{const r=await api('/api/admin/push',{method:'POST',body:{title,body}});$('#pushreport').textContent=`Accettate dal servizio push: ${r.accepted}/${r.total}. Iscrizioni scadute: ${r.expired}. Errori: ${r.failed}.`;await loadAdminData();}catch(err){$('#pushreport').textContent=err.message;}finally{btn.disabled=false;}}
async function enablePush(){const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1),standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone;if(ios&&!standalone)return toast('Su iPhone installa la PWA e aprila dalla schermata Home. Poi attiva le notifiche.');if(!('Notification'in window)||!('PushManager'in window)||!('serviceWorker'in navigator))return toast('Questo browser non supporta le notifiche push. Prova dall’app installata.');const permission=await Notification.requestPermission();if(permission!=='granted')return toast('Permesso non concesso. Puoi cambiarlo nelle impostazioni del dispositivo.');try{const reg=await navigator.serviceWorker.ready,info=await api('/api/push/key');let sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:un64(info.publicKey.replace(/-/g,'+').replace(/_/g,'/'))});await api('/api/push/subscribe',{method:'POST',body:{subscription:sub.toJSON(),name:member(me)}});localStorage.setItem('cc-push-registered','1');pushEnabled=true;render();toast('Notifiche attivate su questo dispositivo');}catch(err){toast('Attivazione non riuscita: '+err.message);}}
async function disablePush(){try{const reg=await navigator.serviceWorker.getRegistration(),sub=await reg?.pushManager.getSubscription();if(sub){try{await api('/api/push/unsubscribe',{method:'POST',body:{endpoint:sub.endpoint}});}finally{await sub.unsubscribe();}}localStorage.removeItem('cc-push-registered');pushEnabled=false;render();toast('Notifiche disattivate');}catch(err){toast(err.message);}}
async function boot(){await loadPlatform();try{const saved=localStorage.getItem('cc-key'),vault=localStorage.getItem('cc-vault');if(saved&&vault&&needsLogin)lockScreen('Inserisci la password del circo per ricollegarti.');else if(saved&&vault){key=await crypto.subtle.importKey('raw',un64(saved),'AES-GCM',true,['encrypt','decrypt']);envelope=JSON.parse(vault);state=validState(await decrypt(envelope,key));current=state.groups[0].id;render();}else lockScreen();}catch{localStorage.removeItem('cc-key');lockScreen('Accedi di nuovo per aprire l’archivio.');}if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}
boot();
